// 200-Decal library for the Canva-grade Design Studio.
// 10 categories × 20 decals = 200 unique, recolorable vector decals.
//
// Every SVG uses `currentColor` so the studio can tint any decal to the active
// ink (or a per-layer override) without re-rendering.  Paths are kept compact
// (single path per shape where possible) for fast rendering and minimal parse
// cost when the studio hot-loads thousands of designs.
//
// Structure is deliberately flat & appendable: add a new `d(...)` line to any
// category array and the rest of the engine (search, layer toolbar, sticker
// book panel, palette swaps) picks it up automatically. Categories 11+ can be
// pushed with the same shape without touching the renderer.

export type Decal = {
  id: string;
  label: string;
  /** Lowercase search keywords used by the inline sticker search. */
  tags: string[];
  /** Inline SVG markup. Uses currentColor — wraps with the parent's `color`. */
  svg: string;
};

export type DecalCategory = {
  id: string;
  label: string;
  blurb?: string;
  decals: Decal[];
};

const d = (id: string, label: string, tags: string[], svg: string): Decal => ({
  id,
  label,
  tags: tags.map((t) => t.toLowerCase()),
  svg,
});

